#include <stdio.h>

int main(void) {
    int conta, inv, d1, d2, d3, soma, digito;
    scanf("%d", &conta);
    d1 = conta / 100;
    d2 = (conta % 100) / 10;
    d3 = conta % 10;
    inv = d3 * 100 + d2 * 10 + d1;
    soma = conta + inv;
    d1 = (soma / 100) * 1;
    d2 = ((soma % 100) / 10) * 2;
    d3 = (soma % 10) * 3;
    digito = (d1 + d2 + d3) % 10;
    printf("%d\n", digito);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n, horas, minutos, segundos;
    scanf("%d", &n);
    horas = n / 3600;
    minutos = (n % 3600) / 60;
    segundos = n % 60;
    printf("%d:%d:%d\n", horas, minutos, segundos);
    return 0;
}

#include <stdio.h>

int main(void) {
    int total_dias, anos, meses, dias;
    scanf("%d", &total_dias);
    anos = total_dias / 365;
    meses = (total_dias % 365) / 30;
    dias = (total_dias % 365) % 30;
    printf("%d\n%d\n%d\n", anos, meses, dias);
    return 0;
}

#include <stdio.h>
#include <math.h>

int main(void) {
    double x1, y1, x2, y2, dist;
    scanf("%lf %lf %lf %lf", &x1, &y1, &x2, &y2);
    dist = sqrt(pow(x2 - x1, 2) + pow(y2 - y1, 2));
    printf("%.4f\n", dist);
    return 0;
}

#include <stdio.h>

int main(void) {
    double a, b, c;
    const double pi = 3.14159;
    scanf("%lf %lf %lf", &a, &b, &c);
    printf("%.3f\n", (a * c) / 2.0);
    printf("%.3f\n", pi * c * c);
    printf("%.3f\n", ((a + b) * c) / 2.0);
    printf("%.3f\n", b * b);
    printf("%.3f\n", a * b);
    return 0;
}

#include <stdio.h>

int main(void) {
    int cod1, qtd1, cod2, qtd2;
    double val1, val2, total;
    scanf("%d %d %lf", &cod1, &qtd1, &val1);
    scanf("%d %d %lf", &cod2, &qtd2, &val2);
    total = qtd1 * val1 + qtd2 * val2;
    printf("VALOR A PAGAR: R$ %.2f\n", total);
    return 0;
}

#include <stdio.h>

int main(void) {
    int tempo, velocidade;
